const {chromium}=require('playwright');const SP=__dirname+'/p.html';
const UA='Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 YaBrowser/24.6 Mobile/15E148 Safari/604.1';
const VIEWS=[['desktop 1440×900',{viewport:{width:1440,height:900}}],['phone 390×844',{viewport:{width:390,height:844},isMobile:true,hasTouch:true,userAgent:UA}],['phone 844×390',{viewport:{width:844,height:390},isMobile:true,hasTouch:true,userAgent:UA}]];
(async()=>{const b=await chromium.launch();const results={};
for(const [vname,opts] of VIEWS){
 const ctx=await b.newContext(opts);const p=await ctx.newPage();const errs=[];p.on('pageerror',e=>errs.push(e.message));
 const mob=!!opts.isMobile;
 const ev=(f,a)=>p.evaluate(f,a);
 const setSel=async(id,v)=>{await p.evaluate(([id,v])=>{const s=document.getElementById(id);s.value=v;s.dispatchEvent(new Event('change',{bubbles:true}))},[id,v]);await p.waitForTimeout(250)};
 const press=async sel=>{const l=p.locator(sel).first();await ev(()=>{if(document.querySelector('#player'))showUi()});try{if(mob)await l.tap({timeout:2500});else await l.click({timeout:2500});}catch(e){const info=await ev(sel=>{const e=document.querySelector(sel);if(!e)return 'нет элемента '+sel;const r=e.getBoundingClientRect();const h=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);return sel+' перекрыт '+(h?(h.tagName+'.'+h.className).slice(0,50):'ничем')+' pe='+getComputedStyle(e).pointerEvents+' hidden='+e.closest('[hidden]')+' '+Math.round(r.top)+'/'+innerHeight},sel);throw new Error(info)}await p.waitForTimeout(250)};
 const go=async h=>{await ev(h=>{location.hash=h},h);await p.waitForTimeout(400)};
 const res=[];const T=async(name,fn)=>{try{const ok=await fn();res.push([name,ok?'OK':'FAIL'])}catch(e){res.push([name,'FAIL: '+e.message.split('\n')[0].slice(0,90)])}};
 await p.goto('file://'+SP+'#player');await p.waitForTimeout(600);
 const st=()=>ev(()=>({t:P.t,playing:P.playing,fs:document.querySelector('.app').classList.contains('fs'),title:(document.querySelector('.pl-title div:last-child')||{}).textContent,muted:P.muted,rate:P.rate,q:P.q,dub:S.dub,hash:location.hash}));
 const ppSel=mob?'[data-pl=pp]':'#pp', rwSel=mob?'[data-pl=rw]':'#rw', fwSel=mob?'[data-pl=fw]':'#fw';
 await T('Пауза',async()=>{await press(ppSel);return (await st()).playing===false});
 await T('Воспроизвести',async()=>{await press(ppSel);return (await st()).playing===true});
 await T('Перемотка −10 с',async()=>{await ev(()=>{P.t=300});await press(rwSel);return Math.abs((await st()).t-290)<2.5});
 await T('Перемотка +10 с',async()=>{await ev(()=>{P.t=300});await press(fwSel);return Math.abs((await st()).t-310)<2.5});
 await T('Таймлайн (клик/тап в середину)',async()=>{const bx=await p.locator('#tl').boundingBox();await ev(()=>document.querySelector('#player').classList.remove('hide-ui'));if(mob)await p.touchscreen.tap(bx.x+bx.width/2,bx.y+bx.height/2);else await p.mouse.click(bx.x+bx.width/2,bx.y+bx.height/2);await p.waitForTimeout(200);return Math.abs((await st()).t-720)<40});
 await T('Пропустить опенинг',async()=>{await ev(()=>{P.t=60;playerPaint()});await press('#skip');return (await st()).t>=140});
 await T('Следующая серия',async()=>{const a=(await st()).title;await press('#nextBtn');await p.waitForTimeout(200);return (await st()).title!==a&&/Серия 7/.test((await st()).title)});
 await T('Предыдущая серия',async()=>{await press('#prevBtn');return /Серия 6/.test((await st()).title)});
 await T('Громкость (выкл/вкл)',async()=>{await press('#volBtn');const a=(await st()).muted;await press('#volBtn');return a===true&&(await st()).muted===false});
 await T('Настройки плеера: открыть',async()=>{await press('#plSetBtn');return await ev(()=>!document.querySelector('#plSetPop').hidden)});
 await T('Настройки: скорость 1.5×',async()=>{await press('[data-rate="1.5"]');return (await st()).rate===1.5});
 await T('Настройки: качество 720p',async()=>{await press('#plSetBtn');await press('[data-q="720p"]');return (await st()).q==='720p'});
 await T('Озвучка: открыть список',async()=>{await press('#dubBtn');return await ev(()=>!document.querySelector('#dubPop').hidden)});
 await T('Озвучка: выбрать «Студия Б»',async()=>{await press('[data-pdub="1"]');return (await st()).dub===1});
 await T('Озвучка: недоступная не выбирается',async()=>{await press('#dubBtn');await p.locator('#dubPop button.off').click({force:true});await p.waitForTimeout(200);const d=(await st()).dub;await ev(()=>{P.dubOpen=false;document.querySelector('#dubPop').hidden=true});return d===1});
 await T('Тап вне меню закрывает его',async()=>{await press('#plSetBtn');const o=await ev(()=>!document.querySelector('#plSetPop').hidden);const bx=await p.locator('.frame-art').boundingBox();if(mob)await p.touchscreen.tap(bx.x+bx.width*0.3,bx.y+bx.height*0.45);else await p.mouse.click(bx.x+bx.width*0.3,bx.y+bx.height*0.45);await p.waitForTimeout(200);return o&&await ev(()=>document.querySelector('#plSetPop').hidden)});
 await T('Тост не перекрывает кнопки',async()=>{await ev(()=>toast('Проверка тоста',null,null,true));await p.waitForTimeout(100);await press('#dubBtn');const o=await ev(()=>!document.querySelector('#dubPop').hidden);await press('#dubBtn');return o});
 await T('Серии: открыть панель',async()=>{await press('#epBtn');return await ev(()=>!document.querySelector('#eppanel').hidden)});
 await T('Серии: сезон 2',async()=>{await press('[data-season="1"]');return await ev(()=>document.querySelector('[data-season="1"]').getAttribute('aria-pressed')==='true')});
 await T('Серии: выбрать серию 3',async()=>{await press('[data-season="0"]');await press('#eppanel [data-ep="3"]');return /Серия 3/.test((await st()).title)});
 await T('Серии: закрыть',async()=>{await press('#epBtn');await press('[data-act=epClose]');return await ev(()=>document.querySelector('#eppanel').hidden)});
 await T('Что играет: открыть',async()=>{await press('#musicBtn');return await ev(()=>P.mus==='off')});
 await T('Что играет: включить и распознать',async()=>{await press('[data-mus=enable]');return await ev(()=>P.mus==='listening')});
 await T('Что играет: закрыть (повторное нажатие)',async()=>{await press('#musicBtn');return await ev(()=>P.mus===null)});
 await T('Полный экран: кнопка',async()=>{await press('#fsBtn');return (await st()).fs===true});
 await T('Полный экран: выход кнопкой',async()=>{await press('#fsBtn');return (await st()).fs===false});
 await T('Клавиша F',async()=>{await p.keyboard.press('f');const a=(await st()).fs;await p.keyboard.press('Escape');return a===true&&(await st()).fs===false});
 await T('Клавиша S (пропуск опенинга)',async()=>{await ev(()=>{P.t=70;playerPaint()});await p.keyboard.press('s');return (await st()).t>=140});
 await T('Клавиша M',async()=>{await p.keyboard.press('m');const a=(await st()).muted;await p.keyboard.press('m');return a===true});
 await T('Пробел',async()=>{const a=(await st()).playing;await p.keyboard.press('Space');return (await st()).playing!==a});
 await T('Стрелки ←/→',async()=>{await ev(()=>{P.t=400});await p.keyboard.press('ArrowRight');const a=(await st()).t;await p.keyboard.press('ArrowLeft');return Math.abs(a-410)<2.5&&Math.abs((await st()).t-400)<2.5});
 await T('Shift+N',async()=>{const a=(await st()).title;await p.keyboard.press('Shift+N');return (await st()).title!==a});
 await T('Карточка следующей серии: Отмена',async()=>{await ev(()=>{P.playing=true;P.rate=1});await press('#toEnd');await p.waitForTimeout(3200);const shown=await ev(()=>!document.querySelector('#next').hidden);await press('#cancelNext');return shown&&await ev(()=>document.querySelector('#next').hidden)});
 await T('Карточка следующей серии: Смотреть сейчас',async()=>{await go('title');await go('player');await ev(()=>{P.playing=true;P.rate=1});await press('#toEnd');await p.waitForTimeout(3200);await press('#goNext');return (await st()).t<5});
 await T('Касание по спрятанной панели показывает её',async()=>{if(!mob)return true;await go('catalog');await go('player');await ev(()=>{document.querySelector('#player').classList.add('hide-ui')});const bx=await p.locator(fwSel).boundingBox();const t0=(await st()).t;await p.touchscreen.tap(bx.x+bx.width/2,bx.y+bx.height/2);await p.waitForTimeout(200);const vis=await ev(()=>!document.querySelector('#player').classList.contains('hide-ui'));return vis&&Math.abs((await st()).t-t0)<2.5});
 await T('Ошибка: «Выбрать другую озвучку»',async()=>{await setSel('demoPlayer','error');await press('[data-act=pickDub]');return await ev(()=>!document.querySelector('#dubPop').hidden)});
 await T('Ошибка: «Повторить»',async()=>{await ev(()=>{P.dubOpen=false});await setSel('demoPlayer','error');await press('[data-act=plRetry]');const l=await ev(()=>document.querySelector('#demoPlayer').value);await p.waitForTimeout(1400);return l==='loading'&&await ev(()=>document.querySelector('#demoPlayer').value==='play')});
 await T('Нет источников: «Отметить просмотренной»',async()=>{await setSel('demoPlayer','empty');await press('[data-act=markEp]');return await ev(()=>P.marked===true)});
 await T('Нет источников: «Вернуться к тайтлу»',async()=>{await setSel('demoPlayer','empty');await press('.pl-state a[href="#title"]');return (await st()).hash==='#title'});
 await T('Назад (стрелка)',async()=>{await setSel('demoPlayer','play');await go('player');await press('.pl-top a[href="#title"]');return (await st()).hash==='#title'});
 await T('Статус на карточке тайтла',async()=>{await go('title');await press('[data-act=statusMenu]');return await ev(()=>!!document.querySelector('#sheet')||!document.querySelector('#statusMenu').hidden)});
 await T('Переключатель «Плеер:»',async()=>{await ev(()=>closeSheet());await go('player');await setSel('demoPlayer','buffering');return await ev(()=>document.querySelector('#player').classList.contains('st-buffering'))});
 await T('YouTube: Серии',async()=>{await setSel('demoPlayer','yt');await press('#epBtn');return await ev(()=>!document.querySelector('#eppanel').hidden)});
 await T('YouTube: Серии рядом с видео, не поверх',async()=>{return await ev(()=>{const pn=document.querySelector('#eppanel').getBoundingClientRect(),st=document.querySelector('.yt-stage').getBoundingClientRect(),fs=document.querySelector('#fsBtn').getBoundingClientRect();return pn.left>=st.right-1&&pn.top>=fs.bottom-1})});
 await T('YouTube: Просмотрено',async()=>{await ev(()=>{P.epOpen=false});await setSel('demoPlayer','yt');await press('.yt-bar [data-act=markEp]');return await ev(()=>P.marked===true)});
 await T('YouTube: следующая серия',async()=>{await setSel('demoPlayer','yt');const a=(await st()).title;await press('.yt-bar [data-act=ytNext]');return (await st()).title!==a});
 await T('YouTube: конец ролика → Остаться',async()=>{await setSel('demoPlayer','ytend');await press('[data-act=ytStay]');return await ev(()=>document.querySelector('#demoPlayer').value==='yt')});
 await T('YouTube: полный экран',async()=>{await press('#fsBtn');const a=(await st()).fs;await p.keyboard.press('Escape');return a&&!(await st()).fs});
 await T('YouTube: нет видео → доступные серии',async()=>{await setSel('demoPlayer','ytmissing');await press('[data-act=ytEps]');return await ev(()=>!document.querySelector('#eppanel').hidden)});
 await T('Тема',async()=>{await setSel('demoPlayer','play');const a=await ev(()=>document.documentElement.dataset.theme||'');if(mob)await p.locator('#protoToggle').tap();await p.locator('#themeBtn').click();const b2=await ev(()=>document.documentElement.dataset.theme||'');return a!==b2});
 results[vname]={res,errs};await ctx.close();}
await b.close();
for(const [v,{res,errs}] of Object.entries(results)){const bad=res.filter(r=>r[1]!=='OK');console.log(`== ${v}: ${res.length} проверок, не прошло ${bad.length}`);bad.forEach(r=>console.log('   ',r[0],'→',r[1]));if(errs.length)console.log('   JS:',errs.slice(0,3));}
require('fs').writeFileSync(__dirname+'/audit.json',JSON.stringify(results,null,1));
})();
